     * it, reads it back, then adopts it.
     *
     * Only its own kind compiles:
     * ```compile_fail
     * # fn wrong(client: &arachne_runtime::Client, c: &arachne_runtime::InvitationCandidate) {
     * client.adopt_admission(c);
     * # }
     * ```
     */
    func adoptAdmission(candidate: WorkspaceCandidate) throws  -> WorkspaceInfo
    
    /**
     * Adopt a staged invitation registration and return its bearer link.
     */
    func adoptInvitation(candidate: InvitationCandidate) throws  -> InvitationInfo
    
    func adoptJoin(candidate: JoinCandidate) throws  -> WorkspaceInfo
    
    func adoptProtectedPublication(candidate: PublicationCandidate) throws  -> DeliveryReport
    
    /**
     * Adopt a staged inbox candidate: a reception from `poll_protected`, or an
     * acknowledgement or rejection. A received object then waits in the
     * durable inbox; read it with `poll_pending_object`.
     */
    func adoptProtectedReception(candidate: ProtectedReceptionCandidate) throws 
    
    func adoptRecovery(candidate: RecoveryCandidate) throws  -> RecoveryAdoption
    
    /**
     * Adopt a saved removal of this member. The session ends: later calls
     * give `Closed`.
     */
    func adoptRemoval(candidate: RemovalCandidate) throws  -> RemovedMembership
    
    /**
     * Advertise one workspace's invitation to nearby devices. Returns
     * whether this device now advertises anything.
     */
    func advertiseNearbyWorkspace(workspace: WorkspaceId?, mode: NearbyMode, invitation: Data, workspaceName: String?) throws  -> Bool
    
    func beginJoin(invitation: Data, checkpoint: Data, displayName: String) throws  -> JoinRequest
    
    /**
     * Begin joining with known peers for the admission exchange.
     */
    func beginJoinWithPeers(invitation: Data, checkpoint: Data, displayName: String, peers: [EndpointId]) throws  -> JoinRequest
    
    /**
     * Interrupt the blocking op in flight (its outbound control
     * exchanges). Not sticky: the latch clears when that op ends, so the
     * next op runs normally.
